insert into public.issuances (slug, type, number, title, date_issued, effectivity_date, tax_types, topics, summary_plain, status, source_url, needs_verification) values
  ('ra-10963', 'RA', '10963', 'Tax Reform for Acceleration and Inclusion (TRAIN) Law', '2017-12-19', '2018-01-01', array['income_tax', 'vat', 'percentage_tax', 'estate_tax', 'donors_tax', 'documentary_stamp_tax', 'withholding_compensation']::text[], array['tax reform', 'graduated rates', '8% option']::text[], 'Rewrote individual income tax rates (₱250,000 exempt), introduced the 8% option for small self-employed taxpayers, set estate and donor''s tax at a flat 6%, and raised documentary stamp tax rates.', 'active', 'https://www.bir.gov.ph/', true),
  ('ra-11534', 'RA', '11534', 'Corporate Recovery and Tax Incentives for Enterprises (CREATE) Act', '2021-03-26', '2021-04-11', array['income_tax', 'percentage_tax']::text[], array['corporate income tax', 'incentives']::text[], 'Cut the corporate income tax to 25% (20% for smaller corporations) from 1 July 2020, temporarily lowered MCIT to 1% and percentage tax to 1% until 30 June 2023, and reformed tax incentives.', 'active', 'https://www.bir.gov.ph/', true),
  ('ra-11976', 'RA', '11976', 'Ease of Paying Taxes Act', '2024-01-05', '2024-01-22', array['penalty', 'registration', 'invoicing', 'vat']::text[], array['file anywhere', 'taxpayer classification', 'invoicing', 'reduced penalties']::text[], 'Lets taxpayers file and pay anywhere, classifies taxpayers by size, lowers penalties for micro and small taxpayers, makes the invoice the main sales document, and removes the ₱500 annual registration fee.', 'active', 'https://www.bir.gov.ph/', true),
  ('ra-12066', 'RA', '12066', 'CREATE MORE Act', null, null, array['income_tax']::text[], array['incentives', 'enhanced deductions']::text[], 'Amends CREATE''s incentive system, including a 20% corporate income tax for registered business enterprises under the enhanced deductions regime.', 'active', 'https://www.bir.gov.ph/', true),
  ('ra-9337', 'RA', '9337', 'Reformed Value-Added Tax Law', null, null, array['vat', 'income_tax']::text[], array['VAT rate']::text[], 'Amended the VAT provisions of the Tax Code, including the 12% VAT rate, and the corporate income tax rate.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-2-98', 'RR', '2-98', 'Withholding tax regulations', null, null, array['withholding_compensation', 'withholding_expanded']::text[], array['withholding', 'ATC']::text[], 'The main regulations on withholding of income tax, amended many times since.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-8-2018', 'RR', '8-2018', 'Implementing the income tax provisions of the TRAIN Law', null, null, array['income_tax']::text[], array['8% option', 'graduated rates']::text[], 'Rules for the new individual income tax rates and the 8% option, including who can elect it and how.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-11-2018', 'RR', '11-2018', 'Amendments to the withholding tax regulations under the TRAIN Law', null, null, array['withholding_compensation', 'withholding_expanded']::text[], array['withholding tables', 'de minimis']::text[], 'Revised the withholding tax tables on compensation and expanded withholding rates to match TRAIN.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-13-2018', 'RR', '13-2018', 'Implementing the VAT provisions of the TRAIN Law', null, null, array['vat']::text[], array['VAT threshold']::text[], 'Rules on the VAT changes under TRAIN, including the ₱3,000,000 VAT threshold.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-6-2024', 'RR', '6-2024', 'Implementing the penalty provisions of the Ease of Paying Taxes Act', null, null, array['penalty']::text[], array['reduced penalties', 'micro and small taxpayers']::text[], 'Rules for the lower surcharge and interest for micro and small taxpayers.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-7-2024', 'RR', '7-2024', 'Implementing the invoicing provisions of the Ease of Paying Taxes Act', null, null, array['invoicing', 'registration']::text[], array['invoicing', 'official receipts']::text[], 'Rules making the sales invoice the main document for sales of goods and services, with official receipts as supplementary documents.', 'active', 'https://www.bir.gov.ph/', true),
  ('rr-8-2024', 'RR', '8-2024', 'Classification of taxpayers under the Ease of Paying Taxes Act', null, null, array['registration', 'penalty']::text[], array['taxpayer classification']::text[], 'Groups taxpayers into micro, small, medium and large by gross sales.', 'active', 'https://www.bir.gov.ph/', true),
  ('rmo-7-2015', 'RMO', '7-2015', 'Revised schedule of compromise penalties', null, null, array['penalty']::text[], array['compromise penalty']::text[], 'Schedule of suggested compromise penalties for violations of the Tax Code.', 'active', 'https://www.bir.gov.ph/', true)
